1571:                 && key.str() != "audio_url" && key.str() != "audio_api_key")
1572:                 warnings.emit(path, "Ignoring unused notes setting: " + std::string(key.str()));
1573:         }
1574:         WorkspaceNotes settings{
1575:             .compression_provider_id = table["compression_provider"].value_or(std::string{}),
1576:             .compression_reasoning_effort = table["compression_reasoning_effort"].value_or(std::string("high")),
1577:             .audio_url = table["audio_url"].value_or(std::string{}),
1578:             .audio_api_key_id = table["audio_api_key"].value_or(std::string{}),
1579:         };
